insert into pg_temp.school967_calligraphy_seed(payload) values ($school967${"slug":"arabic-calligraphy","course":{"title":"الخطوط العربية","description":"رحلة تطبيقية من فهم الحرف والنقطة والسطر إلى النسخ والرقعة والكوفي والثلث والديواني والفارسي والمغربي، مع كتابة كلمات وجمل حقيقية.","category":"الكتابة والأدب"},"stages":[{"index":0,"stage":{"title":"الخط العربي: عين الخطّاط","subtitle":"الأدوات، اتجاه الكتابة، السطر والنقطة","intro":"الخط العربي فنّ كتابة الحروف بنظام بصري واضح، وليس مجرد زخرفة الكلمات. يبدأ الخطاط بملاحظة السطر الذي تستقر عليه أجزاء من الحروف، وأطراف ترتفع فوقه وأقواس تهبط تحته. في الخطوط الموزونة تُستخدم «النقطة» الناتجة عن سن القلم للمقارنة بين الأطوال والمسافات؛ وتختلف النِّسب بحسب نوع الخط ومدرسته. جرّب أولًا كتابة حروف قليلة ببطء، واترك مساحة متقاربة بين الكلمات. الهدف هنا أن تتقن الملاحظة وضبط الحركة قبل السرعة أو الزخرفة.","tips":["ضع الورقة بثبات وارسم سطر إرشاد خفيفًا قبل الكتابة.","لاحظ أجزاء الحروف التي ترتفع فوق السطر أو تهبط تحته.","تمرّن على حركة رأس القلم ببطء؛ لا تُطارد السرعة في البداية.","النقطة وحدة مقارنة في كثير من تقاليد الخط؛ ليست قياسًا ثابتًا لكل الخطوط."],"practice":{"model":"ا ل م","focus":"خط الأساس والنِّسب","instructions":"ارسم الألف واللام والميم ثلاث مرات على سطر واحد. حافظ على استقامة الألف واترك للميم حيزًا مقروءًا."}},"questions":[{"number":0,"kind":"choice","prompt":"لماذا يستخدم الخطاط سطرًا إرشاديًا؟","target":"","options":["لجعل جميع الحروف بالارتفاع نفسه","لإلغاء النقط","لزيادة الزخرفة فقط","لضبط استقرار الحروف والمسافات"],"answerIndex":3,"explanation":"يساعد السطر على انتظام مواقع الحروف ولا يجعل ارتفاعاتها متماثلة."},{"number":1,"kind":"choice","prompt":"إلى ماذا تشير «النقطة» في تقاليد الخط الموزون؟","target":"","options":["لون الحبر","نوع الورق","وحدة مقارنة للنِّسب","علامة انتهاء الجملة"],"answerIndex":2,"explanation":"تُقاس بعض أبعاد الحروف بعدد نقاط القلم، مع اختلاف القواعد باختلاف الخط."},{"number":2,"kind":"choice","prompt":"ما أفضل بداية لتعلّم رسم حرف جديد؟","target":"","options":["تغيير اتجاه الكتابة","تتبّع بنيته ببطء قبل التسريع","تكراره بأقصى سرعة","حذف التفاصيل كلها"],"answerIndex":1,"explanation":"التحكم في شكل الحرف وحركته أولًا يمنع ترسيخ الأخطاء."},{"number":3,"kind":"choice","prompt":"ما الاتجاه العام لكتابة الكلمات العربية؟","target":"","options":["من اليمين إلى اليسار","من اليسار إلى اليمين","من الأعلى إلى الأسفل","في اتجاه دائري"],"answerIndex":0,"explanation":"تسير الكلمات العربية عامة من اليمين إلى اليسار."},{"number":4,"kind":"choice","prompt":"لماذا لا تتساوى جميع أجزاء الحروف على خط واحد؟","target":"","options":["لأن كل حرف منفصل بالضرورة","لأن النقط تحل محل الحروف","لأن جميع الحروف مربعة","لأن بعض الأجزاء تصعد أو تهبط عن السطر"],"answerIndex":3,"explanation":"تصعد بعض السيقان وتهبط بعض الذيول ضمن نظام السطر."},{"number":5,"kind":"choice","prompt":"ما الذي ينبغي مراجعته بعد أول تمرين؟","target":"","options":["زخرفة الهوامش فقط","عدد محاولات الزملاء","وضوح الشكل وانتظام المسافات","عدد الألوان المستعملة"],"answerIndex":2,"explanation":"تبدأ المراجعة بالقراءة الصحيحة والاتزان قبل التحسينات الزخرفية."},{"number":6,"kind":"order","prompt":"رتّب خطوات بدء تدريب الخط بطريقة عملية.","target":"","tokens":["راجع النِّسب","ارسم ببطء","حدّد السطر","جهّز الورقة"],"answer":["جهّز الورقة","حدّد السطر","ارسم ببطء","راجع النِّسب"],"explanation":"التسلسل الصحيح: جهّز الورقة ← حدّد السطر ← ارسم ببطء ← راجع النِّسب. "},{"number":7,"kind":"type","prompt":"أكمل المصطلح: وحدة قياس شائعة في الخط الموزون هي ...","target":"","answer":"النقطة","explanation":"تُستخدم النقطة في قياس نسب كثير من الحروف في بعض الخطوط الموزونة."}]},{"index":1,"stage":{"title":"هندسة الحرف واتصاله","subtitle":"الهيئات الأربع والحروف التي لا تتصل بما بعدها","intro":"يتغيّر شكل الحرف العربي بحسب موقعه: منفردًا وفي أول الكلمة ووسطها وآخرها. ليست هذه أربعة أحرف مختلفة، بل صور سياقية للحرف نفسه. أكثر الحروف يتصل بما يليه، بينما توجد ستة حروف لا تصل الحرف التالي: ا، د، ذ، ر، ز، و؛ وهذه الحروف قد تتصل بما قبلها. لاحظ كلمة «بيت» التي تتصل حروفها، وقارنها بكلمة «ورد» التي تنقطع فيها الوصلات. افهم قواعد الوصل قبل محاولة رسم الكلمات بأسلوب خطي جميل.","tips":["اكتب الباء في صورها: ب، بـ، ـبـ، ـب.","احفظ الحروف الستة التي لا تصل ما بعدها.","انقطاع الوصل داخل الكلمة لا يعني وجود مسافة بين كلمتين.","افصل بين فهم أشكال الحروف وبين اختلاف أسلوب النسخ أو الرقعة."],"practice":{"model":"بـ ـبـ ـب ب  |  بيت  |  ورد","focus":"الصور السياقية والوصل","instructions":"اكتب صور الباء الأربع، ثم كلمتي «بيت» و«ورد». ضع علامة صغيرة عند موضع انقطاع الوصل داخل «ورد»."}},"questions":[{"number":0,"kind":"choice","prompt":"أي مجموعة تتكون من حروف لا تتصل بما بعدها؟","target":"","options":["س ش ص ض ط ظ","ج ح خ ع غ ف","ا د ذ ر ز و","ب ت ث ن ي م"],"answerIndex":2,"explanation":"هذه الأحرف الستة يمكنها الاتصال بما قبلها لكنها لا تصل الحرف التالي."},{"number":1,"kind":"choice","prompt":"أي عبارة صحيحة عن حرف الباء؟","target":"","options":["يُحذف عند بداية الكلمة","له صور تتأثر بموقعه في الكلمة","له صورة واحدة في كل المواقع","لا يتصل بما بعده"],"answerIndex":1,"explanation":"للباء صور منفردة وأولية ووسطية ونهائية بحسب الوصل."},{"number":2,"kind":"choice","prompt":"ماذا يحدث بعد حرف الدال داخل كلمة؟","target":"","options":["يبدأ الحرف التالي بوصلة جديدة دون اتصال بالدال","يتحوّل الدال إلى نقطتين","يلتصق التالي بالدال دائمًا","تُضاف مسافة بين كلمتين"],"answerIndex":0,"explanation":"الدال لا يتصل بالحرف التالي مع بقاء الكلمة واحدة."},{"number":3,"kind":"choice","prompt":"أي الكلمات تصل جميع حروفها في تسلسل واحد؟","target":"","options":["ورد","دار","زور","بيت"],"answerIndex":3,"explanation":"الباء والياء والتاء تتصل بحسب موقعها في كلمة بيت."},{"number":4,"kind":"choice","prompt":"كيف تميّز بين الباء والتاء والثاء في البنية الأساسية؟","target":"","options":["لون الورق","اتجاه قراءة العبارة","عدد النقط ومواقعها","عدد الكلمات في السطر"],"answerIndex":2,"explanation":"تتشابه الهياكل في صور كثيرة وتختلف النقط."},{"number":5,"kind":"choice","prompt":"هل حرف الواو يصل الحرف الذي يأتي بعده؟","target":"","options":["يتصل فقط بحرف الميم","لا، لكنه قد يتصل بما قبله","نعم دائمًا","لا يتصل بأي حرف في أي موضع"],"answerIndex":1,"explanation":"الواو من الحروف الستة التي لا تتصل بما بعدها."},{"number":6,"kind":"order","prompt":"رتّب الصور التعليمية لحرف الباء من المنفرد إلى النهائي.","target":"","tokens":["ـب","ـبـ","بـ","ب"],"answer":["ب","بـ","ـبـ","ـب"],"explanation":"التسلسل الصحيح: ب ← بـ ← ـبـ ← ـب. "},{"number":7,"kind":"type","prompt":"اكتب اسم الحرف الذي يظهر في صور: بـ، ـبـ، ـب.","target":"","answer":"الباء","explanation":"هذه الصور السياقية كلها للحرف نفسه: الباء."}]},{"index":2,"stage":{"title":"النسخ: أساس الحروف","subtitle":"وضوح الحرف وتوزيع النقط والأقواس","intro":"خط النسخ من أشهر الخطوط المخصصة للنصوص المقروءة والنسخ، وتستند إليه أشكال طباعية كثيرة. تمتاز نماذجه التعليمية الواضحة بالتوازن بين السيقان والأقواس والفراغات الداخلية للحروف. سنبدأ بعائلة الباء والتاء والثاء، ثم النون والياء، لأن المقارنة بين هذه الأشكال تعلّم العين موقع النقطة وطريقة قراءة الوصلة. لا تتعجل محاكاة يد خطاط محترف: اكتب «بيت» و«نبت» على سطر واحد وتحقق من وضوح الحروف.","tips":["ميّز الباء بنقطتها السفلى والتاء بنقطتيها العلويتين.","راقب انفتاح الفراغ داخل الحرف وعدم تزاحم الوصلات.","قد تختلف تفاصيل شكل الحرف في النسخ اليدوي بحسب المدرسة.","وازن بين الحرف والكلمة؛ لا تجعل النقطة تحتك بالحرف المجاور."],"practice":{"model":"بيت   نبت   بَتّ","focus":"النسخ الواضح","instructions":"اكتب «بيت» و«نبت» بالنسخ على ثلاثة أسطر. ركّز على موضع النقط والمسافة بين الحروف."}},"questions":[{"number":0,"kind":"choice","prompt":"لماذا يكثر استعمال النسخ للنصوص؟","target":"","options":["لأنه لا يصلح للجمل","لوضوح حروفه وقابليته للقراءة","لأنه بلا نقاط","لأنه لا يصل الحروف"],"answerIndex":1,"explanation":"يمتاز النسخ في كثير من تطبيقاته بوضوح البنية ونظام القراءة."},{"number":1,"kind":"choice","prompt":"أين تقع نقطة الباء في صورها المعتادة؟","target":"","options":["أسفل الحرف","فوق الحرف","على يسار الصفحة","في نهاية السطر دائمًا"],"answerIndex":0,"explanation":"للباء نقطة واحدة أسفل جسم الحرف."},{"number":2,"kind":"choice","prompt":"بماذا تتميز التاء عن الباء عادة؟","target":"","options":["بنقطة أسفل الجسم","بغياب النقاط دائمًا","بأربع نقاط فوقه","بنقطتين فوق الجسم"],"answerIndex":3,"explanation":"للتاء نقطتان فوق البنية المشتركة مع الباء."},{"number":3,"kind":"choice","prompt":"ما العامل الأهم عند تدريب كلمة بالنسخ؟","target":"","options":["ضغط جميع الحروف","ترك الكلمة بلا وصلات","وضوح الحروف واتساق السطر","إخفاء النقاط"],"answerIndex":2,"explanation":"القراءة والتناسب أسبق من الزخرفة."},{"number":4,"kind":"choice","prompt":"أي جزء من الحرف يحتاج إلى مساحة كافية ليبقى واضحًا؟","target":"","options":["ظل الورقة","الفراغ الداخلي والقوس","رأس القلم وحده","علامة الترقيم فقط"],"answerIndex":1,"explanation":"التزاحم قد يغلق الفراغات ويُصعّب قراءة النسخ."},{"number":5,"kind":"choice","prompt":"أي حرف من هذه الحروف تظهر له نقطة واحدة فوقه؟","target":"","options":["ن","ت","ث","ب"],"answerIndex":0,"explanation":"للنون نقطة واحدة أعلى جسم الحرف في صورها المعتادة."},{"number":6,"kind":"order","prompt":"رتّب خطوات نسخ كلمة قصيرة بوضوح.","target":"","tokens":["راجع التوازن","أضف النقط","اكتب الحروف","ارسم السطر"],"answer":["ارسم السطر","اكتب الحروف","أضف النقط","راجع التوازن"],"explanation":"التسلسل الصحيح: ارسم السطر ← اكتب الحروف ← أضف النقط ← راجع التوازن. "},{"number":7,"kind":"type","prompt":"اكتب اسم الخط الذي يُدرّس هنا بوصفه خطًا واضحًا للنصوص المقروءة.","target":"","answer":"النسخ","explanation":"يركّز درس هذه المحطة على خط النسخ، بخطوطه الواضحة واتزانه."}]},{"index":3,"stage":{"title":"النسخ: الكلمات والجمل","subtitle":"اللام والألف والميم وميزان السطر","intro":"بعد ضبط الحروف البسيطة، ننتقل إلى الكلمات القصيرة والجمل المكتملة. انتبه إلى اتصال اللام بالألف في رسم «لا»، وإلى شكل الميم عندما يتغير موقعها. اكتب «سلام» ثم «العلم نور» ببطء مع ترك مسافة واضحة بين الكلمتين. ضع علامات الحركات فقط حين تخدم القراءة أو يطلبها التمرين. الخط الجميل ليس جمع حروف منفصلة؛ بل بناء كلمة متوازنة ثم وضعها ضمن إيقاع الجملة.","tips":["لاحظ وصلة اللام والألف ولا تعزل الحروف بلا سبب.","وازن ارتفاع الألف واللام بالنسبة إلى بقية الحروف.","اترك بين الكلمات مساحة أكبر من الفراغات داخل الكلمة.","اكتب جملة كاملة واقرأها للتأكد من سلامة الكتابة."],"practice":{"model":"العلم نور","focus":"تركيب جملة حقيقية بالنسخ","instructions":"اكتب «العلم نور» ثلاث مرات. استقم بالسطر، وحافظ على صعود اللام والألف ووضوح فراغات الميم والنون."}},"questions":[{"number":0,"kind":"choice","prompt":"أي صورة تمثل اتصال اللام بالألف في كلمة؟","target":"","options":["لا","ـبـ","ـنـ","هـ"],"answerIndex":0,"explanation":"تتصل اللام بالألف في شكل خاص معروف في الكتابة العربية."},{"number":1,"kind":"choice","prompt":"ماذا يجب أن يكون أكبر عادة؟","target":"","options":["الفراغ داخل كل حرف مقارنة بالصفحة","حجم النقاط مقارنة بالكلمات","المسافة بين الحروف المتصلة دائمًا","الفراغ بين كلمتين مقارنة بوصلات الحروف"],"answerIndex":3,"explanation":"فراغ الكلمات يُعين القارئ على تمييز حدودها."},{"number":2,"kind":"choice","prompt":"أي تمرين أفضل لتحسين كتابة الجمل؟","target":"","options":["تغيير اتجاه الكلمات","حذف الحروف الصاعدة","كتابة عبارة حقيقية ثم مراجعتها","نسخ نقاط عشوائية فقط"],"answerIndex":2,"explanation":"الجمل الكاملة تدرب انتظام السطور والمسافات."},{"number":3,"kind":"choice","prompt":"ما الذي ينبغي الانتباه إليه عند رسم اللام والألف؟","target":"","options":["جعلهما تحت السطر كاملًا","ارتفاعهما واتصالهما المناسب","إخفاؤهما داخل الكلمة","وضع النقط على اللام"],"answerIndex":1,"explanation":"اللام والألف من الحروف الصاعدة ويجب ضبط تناسبهما."},{"number":4,"kind":"choice","prompt":"لماذا لا نبدأ بالزخارف المعقدة؟","target":"","options":["لأن إتقان الشكل والقراءة يسبق الزينة","لأن الخط العربي بلا زينة","لأن الزخرفة تلغي النقط","لأن الورق لا يحتمل الزخارف"],"answerIndex":0,"explanation":"وضوح الكلمات وتوازنها أساس التصميم الناجح."},{"number":5,"kind":"choice","prompt":"أي عبارة مثال لجملة عربية قصيرة مكتملة المعنى؟","target":"","options":["ب م ن ت","ألف لام ميم","سطر نقطة قلم","العلم نور"],"answerIndex":3,"explanation":"«العلم نور» جملة عربية مفيدة يمكن التدرب على توزيع كلماتها."},{"number":6,"kind":"order","prompt":"رتّب كلمات الجملة العربية الصحيحة.","target":"","tokens":["للإنسان","نور","العلم"],"answer":["العلم","نور","للإنسان"],"explanation":"التسلسل الصحيح: العلم ← نور ← للإنسان. "},{"number":7,"kind":"type","prompt":"اكتب الكلمة الناقصة: «العلم ...».","target":"","answer":"نور","explanation":"الجملة الحقيقية الكاملة هي «العلم نور»."}]},{"index":4,"stage":{"title":"الرقعة: السرعة المنضبطة","subtitle":"اختصار الأشكال وقلة الزخرفة","intro":"خط الرقعة أسلوب عملي واسع الانتشار للكتابة اليدوية اليومية. يميل في نماذجه الشائعة إلى الاختصار وصغر بعض الحروف وإلى حركة أكثر اقتصادًا من النسخ، لكن له قواعد وليس كتابة عشوائية. قارن كلمة «قلم» مكتوبة بوضوح بكتابتها على نحو سريع: هل بقيت الحروف مقروءة؟ لا تحكم على الرقعة من نوع خط رقمي واحد؛ فالقواعد اليدوية تظهر في حركة القلم والنِّسب. جرّب كتابة الكلمة ثم زد السرعة قليلًا مع الحفاظ على القراءة.","tips":["الرقعة ليست نسخًا مشوّهًا أو كتابة بلا قواعد.","قلّل الحركات غير اللازمة دون فقدان بنية الحرف.","حافظ على مواضع النقط والتمييز بين الحروف.","اختبر سرعة الكتابة مع بقاء الكلمة مقروءة."],"practice":{"model":"قلم   كتاب   عمل","focus":"الرقعة السريعة الواضحة","instructions":"اكتب «قلم، كتاب، عمل» ببطء أولًا، ثم أعد كتابتها بسرعة متوسطة دون اختفاء النقط أو الوصلات."}},"questions":[{"number":0,"kind":"choice","prompt":"أي وصف أقرب إلى استعمال الرقعة؟","target":"","options":["حفر الأحجار القديمة فقط","تزيين القبب حصريًا","طباعة الجداول الرقمية","الكتابة اليدوية اليومية السريعة"],"answerIndex":3,"explanation":"الرقعة خط عملي شائع للكتابة اليومية."},{"number":1,"kind":"choice","prompt":"ما المقصود بالاختصار في الرقعة؟","target":"","options":["إلغاء الكلمات غير المهمة","تكرار الحرف بلا توقف","اقتصاد الحركة مع بقاء الحرف مقروءًا","حذف كل نقاط الحروف"],"answerIndex":2,"explanation":"يقوم الاختصار على حركة أكثر اقتصادية لا على إلغاء الفروق الأساسية."},{"number":2,"kind":"choice","prompt":"هل السرعة وحدها كافية للرقعة الجيدة؟","target":"","options":["نعم ولو اختلف اتجاه الكتابة","لا، لا بد من نظام ووضوح","نعم مهما ضاعت الحروف","نعم دون تدريب"],"answerIndex":1,"explanation":"التوازن والقراءة شرط قبل زيادة السرعة."},{"number":3,"kind":"choice","prompt":"كيف تختلف الرقعة عن النسخ غالبًا؟","target":"","options":["بإيجاز بعض الأشكال وسرعة الحركة","بانعدام الاتصال بين الحروف","بانعدام جميع النقط","بكتابتها من اليسار إلى اليمين"],"answerIndex":0,"explanation":"تختلف النِّسب والأساليب بما يخدم سرعة الأداء في الرقعة."},{"number":4,"kind":"choice","prompt":"ماذا تفعل عند اختلاط شكل حرفين أثناء السرعة؟","target":"","options":["تكتب أسرع","تحذف الكلمة","ترسم زخرفة فوقهما","تخفض السرعة وتراجع موضع النقط"],"answerIndex":3,"explanation":"لا قيمة للسرعة إذا فقد القارئ تمييز الحروف."},{"number":5,"kind":"choice","prompt":"أي مادة تدريب مناسبة لبداية الرقعة؟","target":"","options":["أرقام عشوائية بلا حروف","رسم دون قراءة","كلمات مألوفة قصيرة","نصوص زخرفية متشابكة جدًا"],"answerIndex":2,"explanation":"الكلمات القصيرة تسمح بضبط الحركة قبل الانتقال إلى جمل."},{"number":6,"kind":"order","prompt":"رتّب خطة تدريج السرعة في تدريب الرقعة.","target":"","tokens":["تحقق من الوضوح","زد السرعة","اضبط الحروف","اكتب ببطء"],"answer":["اكتب ببطء","اضبط الحروف","زد السرعة","تحقق من الوضوح"],"explanation":"التسلسل الصحيح: اكتب ببطء ← اضبط الحروف ← زد السرعة ← تحقق من الوضوح. "},{"number":7,"kind":"type","prompt":"اكتب اسم خط الكتابة اليدوية اليومية الذي تدرسه المحطة.","target":"","answer":"الرقعة","explanation":"الرقعة معروف باقتصاد الحركة وسهولة استعماله في الكتابة اليومية."}]},{"index":5,"stage":{"title":"الرقعة: الجملة والإيقاع","subtitle":"سطور عملية وعبارات كاملة","intro":"الكتابة الجيدة بالرقعة تتطلب ثبات الإيقاع عبر كلمة وجملة، لا عبر حرف منفرد فقط. اختر عبارة قصيرة ذات معنى مثل «الوقت ثمين» أو «العمل أساس النجاح». ابدأ بالسطر ثم وزّع الكلمات بحيث لا تلتصق بغيرها، وراقب ارتفاع الحروف الصاعدة. جرّب ثلاث محاولات: الأولى دقيقة، الثانية متوسطة السرعة، والثالثة أسرع قليلًا. لا تُقيّم تحسن الخط بمجرد الوقت؛ راقب وضوح الكلمة، مواضع النقط، وتناسق المسافات.","tips":["استخدم جملة حقيقية بدل سلاسل حروف بلا معنى.","قارن بين نسخة بطيئة ونسخة أسرع؛ تحقّق من القراءة.","اترك مساحة منتظمة بين كلمتي الجملة.","تجنب ضغط الكلمة الثانية عند الاقتراب من نهاية السطر."],"practice":{"model":"الوقت ثمين","focus":"الرقعة في جمل متصلة","instructions":"اكتب «الوقت ثمين» ثم «العمل أساس النجاح». جرّب إيقاعًا أسرع قليلًا في المحاولة الثالثة، وراقب وضوح كل كلمة."}},"questions":[{"number":0,"kind":"choice","prompt":"أي معيار يُظهر تحسن الخط عند زيادة السرعة؟","target":"","options":["زيادة الحبر المستخدم","عدد الزخارف في السطر","ثبات القراءة واتزان المسافات","السرعة وحدها"],"answerIndex":2,"explanation":"التحسن الحقيقي يجمع الإيقاع والوضوح."},{"number":1,"kind":"choice","prompt":"ما التمرين الأنسب لهذه المرحلة؟","target":"","options":["رسم نقطة وحيدة","جملة كاملة ذات معنى","حرف منفرد فقط إلى الأبد","قصاصة بلا كلمات"],"answerIndex":1,"explanation":"المحطة تركز على توحيد أداء الحروف داخل الجملة."},{"number":2,"kind":"choice","prompt":"لماذا نراجع المسافة بين الكلمات؟","target":"","options":["لتظل حدود الكلمات واضحة","لأن كل الحروف منفصلة","لزيادة طول السطر دائمًا","لإخفاء الأخطاء"],"answerIndex":0,"explanation":"المسافات المنتظمة تساعد على قراءة العبارة بسهولة."},{"number":3,"kind":"choice","prompt":"ما التصرف الصحيح عند فقدان وضوح آخر كلمة؟","target":"","options":["حذف علامات الاتصال","إلغاء السطر","تزيين الكلمة فقط","تقليل السرعة وإعادة التمرين"],"answerIndex":3,"explanation":"اضبط إيقاع الكتابة في كل أجزاء الجملة لا بدايتها فقط."},{"number":4,"kind":"choice","prompt":"أي ممارسة تدعم تعلم الرقعة أكثر؟","target":"","options":["تغيير اتجاه الكتابة","ترك النقط كلها","المقارنة بين محاولات متدرجة السرعة","الانتقال فورًا إلى الديواني"],"answerIndex":2,"explanation":"المقارنة المرحلية تكشف أخطاء السرعة."},{"number":5,"kind":"choice","prompt":"متى يمكن الانتقال إلى كتابة أسرع؟","target":"","options":["إذا ازدحمت الكلمات","بعد ثبات أشكال الحروف وقراءتها","قبل تعلم الأشكال الأساسية","إذا سقطت النقاط"],"answerIndex":1,"explanation":"لا تنتقل إلى السرعة على حساب الوضوح."},{"number":6,"kind":"order","prompt":"رتّب كلمات جملة صحيحة تتدرب عليها بالرقعة.","target":"","tokens":["النجاح","أساس","العمل"],"answer":["العمل","أساس","النجاح"],"explanation":"التسلسل الصحيح: العمل ← أساس ← النجاح. "},{"number":7,"kind":"type","prompt":"أكمل العبارة المستخدمة في تدريب هذه المحطة: «الوقت ...».","target":"","answer":"ثمين","explanation":"«الوقت ثمين» عبارة مكتملة تُدرّب كتابة كلمتين بإيقاع متوازن."}]},{"index":6,"stage":{"title":"الكوفي: الحرف والبناء الهندسي","subtitle":"التوازن بين الزوايا والمساحات","intro":"الكوفي اسم لعائلة تاريخية واسعة من أساليب الكتابة العربية؛ وبعض أنواعه، خاصة الكوفي الهندسي، يستخدم الزوايا والتقسيمات المنتظمة. ليس كل ما يسمى «كوفيًا» مربعًا، ولا ينبغي الخلط بين النقوش التاريخية المتنوعة وتمارين المربعات الحديثة. في هذه المحطة سنستعمل شبكة بسيطة لتنظيم الحروف، ونقارن توزيع المساحات البيضاء بالأجزاء المكتوبة. عند تصميم «نور»، ابدأ بقراءة الكلمة، ثم جرّب بناء شكل هندسي يبقي الحروف مميزة.","tips":["لا تعتبر كل أنواع الكوفي هندسية أو مربعة بالدرجة نفسها.","ابدأ من وضوح الكلمة قبل زخرفة محيطها.","راقب نسبة المساحة البيضاء إلى الأجزاء المرسومة.","الشبكة وسيلة تعليمية للتناسب وليست قاعدة تاريخية واحدة لكل الكوفي."],"practice":{"model":"نور","focus":"الكوفي الهندسي الإرشادي","instructions":"ارسم شبكة خفيفة من المربعات ووزّع كلمة «نور» داخل مستطيل. ابدأ بنسخة مقروءة قبل إضافة زوايا أو عناصر زخرفية."}},"questions":[{"number":0,"kind":"choice","prompt":"هل جميع أنواع الخط الكوفي مربعة الشكل؟","target":"","options":["لا يستخدم إلا للأرقام","لا، الكوفي عائلة أساليب متعددة","نعم دون استثناء","نعم ولا تحتوي أقواسًا أبدًا"],"answerIndex":1,"explanation":"الكوفي تاريخيًا متنوع، والكوفي الهندسي نوع من أنواعه."},{"number":1,"kind":"choice","prompt":"ما فائدة الشبكة في تمرين الكوفي الهندسي؟","target":"","options":["تنظيم المساحات والأبعاد","حذف الحروف","إخفاء الكلمة","زيادة عدد النقاط"],"answerIndex":0,"explanation":"تساعد الشبكة التعليمية على ضبط المحاذاة والتناسب."},{"number":2,"kind":"choice","prompt":"بماذا نبدأ عند تصميم كلمة هندسية؟","target":"","options":["إضافة زخارف كثيفة أولًا","حذف أجزاء من الكلمة","تغيير اتجاه العربية","التأكد من قراءة الحروف"],"answerIndex":3,"explanation":"من المهم أن تبقى الكلمة مقروءة قبل الزخرفة."},{"number":3,"kind":"choice","prompt":"ما الذي يحتاج إلى توازن مع المساحات المرسومة؟","target":"","options":["أرقام المحطات","لون الطاولة","الفراغات البيضاء","عدد الأوراق"],"answerIndex":2,"explanation":"الفراغ جزء أساسي من التكوين الهندسي."},{"number":4,"kind":"choice","prompt":"أين نجد أشكالًا من الكتابة الكوفية تاريخيًا؟","target":"","options":["في الجداول الرياضية وحدها","في نقوش ومخطوطات وزخارف معمارية","في تطبيقات الهواتف فقط","في الخرائط الحديثة حصريًا"],"answerIndex":1,"explanation":"استُخدمت أشكال كوفية في المخطوطات والعمارة."},{"number":5,"kind":"choice","prompt":"ما الفرق بين الدرس التاريخي والتمرين الهندسي؟","target":"","options":["التمرين تبسيط لا يمثل كل تنوع الكوفي","لا فرق بينهما أبدًا","الكوفي كله من شبكة واحدة","التمرين يزيل ضرورة القراءة"],"answerIndex":0,"explanation":"نستخدم الشبكة للتعلم، لا لادعاء تمثيل كل المذاهب التاريخية."},{"number":6,"kind":"order","prompt":"رتّب خطوات تصميم كلمة مقروءة على شبكة هندسية.","target":"","tokens":["راجع الوضوح","وزّع الحروف","حدّد الشبكة","اختر الكلمة"],"answer":["اختر الكلمة","حدّد الشبكة","وزّع الحروف","راجع الوضوح"],"explanation":"التسلسل الصحيح: اختر الكلمة ← حدّد الشبكة ← وزّع الحروف ← راجع الوضوح. "},{"number":7,"kind":"type","prompt":"اكتب اسم الخط الذي قد يأتي في أنماط هندسية وزخرفية.","target":"","answer":"الكوفي","explanation":"الكوفي عائلة واسعة من الخطوط تشمل أساليب هندسية."}]},{"index":7,"stage":{"title":"الثلث: الإيقاع والزخرفة","subtitle":"حروف كبيرة وتراكيب احتفالية","intro":"يُعرف خط الثلث في العديد من الأعمال الفنية والعناوين الكبيرة بامتداد بعض الحروف وبحركة منحنية وتراكيب زُخرفية متقنة. يحتاج إتقانه العملي إلى تدريب طويل على القلم المقطوط والنِّسب، ولذلك لا نعامل حروفه كأنها مجرد تكبير لخط النسخ. درسنا يركز على التمييز بين الخط المقروء اليومي والخط الزخرفي المخصص للعرض، ثم تخطيط تكوين بسيط لكلمة «العلم». اجعل الفراغات تخدم الحروف ولا تُخفيها.","tips":["يمتاز الثلث في تطبيقات كثيرة بحضور كبير وعناصر زخرفية.","ليس مجرد تكبير لأشكال النسخ.","ارسم مخطط الحروف أولًا قبل محاولة تركيبها.","لا تضع الزخرفة فوق موضع حرف أو نقطة ضرورية."],"practice":{"model":"العلم","focus":"تصميم كلمة عرض بالثلث","instructions":"اكتب «العلم» في إطار أفقي واسع، وجرّب توزيع أطوال الألف واللام حول الحروف الأخرى، ثم راجع القراءة."}},"questions":[{"number":0,"kind":"choice","prompt":"أين يستخدم الثلث كثيرًا؟","target":"","options":["في العناوين والزخارف المعمارية","في تدوين ملاحظات سريعة فقط","في جداول الحساب حصريًا","في اللوحات الرقمية فقط"],"answerIndex":0,"explanation":"يلائم الثلث الأعمال المعمارية والعناوين المزخرفة."},{"number":1,"kind":"choice","prompt":"هل الثلث مجرد تكبير لخط النسخ؟","target":"","options":["نعم لا تختلف الحروف إلا بالحجم","هو نوع من الترقيم","لا يحتوي أقواسًا","لا، له قواعد وتراكيب مميزة"],"answerIndex":3,"explanation":"لكل خط ضوابطه وأسلوب بنائه."},{"number":2,"kind":"choice","prompt":"ما الذي يجب حمايته عند تركيب الحروف زخرفيًا؟","target":"","options":["لون الإطار فقط","حجم الورق وحده","وضوح بنية الكلمة ونقطها","عدد الصور على الهاتف"],"answerIndex":2,"explanation":"لا ينبغي أن تلغي الزخرفة القدرة على قراءة النص."},{"number":3,"kind":"choice","prompt":"ما أهم عنصر في تدريب الثلث للمبتدئ؟","target":"","options":["تغيير اتجاه القراءة","تخطيط التكوين قبل الزينة","السرعة القصوى","حذف الحروف المكررة"],"answerIndex":1,"explanation":"التخطيط الأولي يحسن توزيع الحروف والمسافات."},{"number":4,"kind":"choice","prompt":"ما صفة شائعة في الثلث الزخرفي؟","target":"","options":["امتدادات وحركات منحنية وتركيب","حروف منفصلة كلها","غياب الخطوط الصاعدة","انعدام الزخارف"],"answerIndex":0,"explanation":"تظهر في الثلث امتدادات منحنية وتركيبات متقنة."},{"number":5,"kind":"choice","prompt":"لماذا يحتاج الثلث إلى ممارسة طويلة؟","target":"","options":["لأنه يُكتب بلا حروف","لأنه يكتب من اليسار دائمًا","لأنه بلا سطر","لدقة النِّسب وحركة القلم والتركيب"],"answerIndex":3,"explanation":"التحكم بالسن والزوايا والامتدادات مهارة تتطور تدريجيًا."},{"number":6,"kind":"order","prompt":"رتّب مراحل إعداد كلمة زخرفية واضحة.","target":"","tokens":["راجع القراءة","وازن الفراغات","حدّد الامتدادات","ارسم مخططًا"],"answer":["ارسم مخططًا","حدّد الامتدادات","وازن الفراغات","راجع القراءة"],"explanation":"التسلسل الصحيح: ارسم مخططًا ← حدّد الامتدادات ← وازن الفراغات ← راجع القراءة. "},{"number":7,"kind":"type","prompt":"اكتب اسم خط العناوين الكبيرة والتكوينات الزخرفية في هذه المحطة.","target":"","answer":"الثلث","explanation":"يُستخدم الثلث كثيرًا في التراكيب الزخرفية والعناوين."}]},{"index":8,"stage":{"title":"الديواني: انسياب التكوين","subtitle":"تقارب الحروف وحركة السطر","intro":"نشأ الخط الديواني في البيئة العثمانية وتطوّر في أعمال الدواوين والمراسلات الرسمية. من سماته في كثير من نماذجه كثافة التراكيب وتقارب الحروف والانحناءات المتدفقة. قد تبدو الكلمة ممتعة بصريًا وصعبة القراءة إن تراكمت عناصرها، لذلك ندرس العلاقة بين الجمال والوضوح. لا تقلّد التداخل المعقد قبل فهم أشكال الحروف. اكتب «سلام» في مساحة منحنية خفيفة، ووازن بين التقارب والمسافة التي تسمح بتحديد الحروف.","tips":["ارتبط الديواني تاريخيًا بالمراسلات والدواوين العثمانية.","قد تتقارب حروفه وتتشابك في نماذجه الزخرفية.","لا تخلط بين انسياب السطر وإخفاء بنية الحرف.","ابدأ بكلمة قصيرة قبل محاولة تركيبات مزدحمة."],"practice":{"model":"سلام","focus":"انسياب الحروف وتوازن الكثافة","instructions":"اكتب «سلام» على سطر بسيط، ثم جرّب منحنى إرشاديًا خفيفًا أسفلها مع الحفاظ على قابلية قراءتها."}},"questions":[{"number":0,"kind":"choice","prompt":"بأي بيئة تاريخية ارتبط تطور الديواني؟","target":"","options":["أوراق الاختبارات الحديثة فقط","الحفر الروماني وحده","المخطوطات الصينية حصريًا","الدواوين والمراسلات العثمانية"],"answerIndex":3,"explanation":"يرتبط الديواني بتقاليد الكتابة في الدواوين العثمانية."},{"number":1,"kind":"choice","prompt":"ما سمة تظهر في نماذج ديوانية كثيرة؟","target":"","options":["حروف مربعة دائمًا","سطر بلا انحناءات قط","تقارب الحروف وانسياب المنحنيات","تباعد جميع الحروف بلا وصل"],"answerIndex":2,"explanation":"تتميز نماذج ديوانية بالكثافة والتدفق."},{"number":2,"kind":"choice","prompt":"ما الخطر عند زيادة التشابك بلا تدريب؟","target":"","options":["تحسن جميع الحروف","ضعف قراءة الكلمة","زيادة صحة الإملاء تلقائيًا","اختفاء الحاجة إلى النقط"],"answerIndex":1,"explanation":"يجب ضبط التداخل حتى لا يتعذر تمييز الحروف."},{"number":3,"kind":"choice","prompt":"بماذا يبدأ تمرين الديواني للمبتدئ؟","target":"","options":["كلمة قصيرة واضحة قبل التركيب المعقد","رسالة طويلة متشابكة","رسم عشوائي دون كلمات","تكبير النقاط فقط"],"answerIndex":0,"explanation":"يتيح التدرج من البسيط إلى المعقد فهم الحركة."},{"number":4,"kind":"choice","prompt":"ما الذي لا يميز الديواني تحديدًا؟","target":"","options":["الحركة المنحنية","تاريخ الدواوين","إمكان التداخل الزخرفي","كونه خط الملاحظات المدرسية السريع الشائع"],"answerIndex":3,"explanation":"الرقعة هو الشائع للكتابة اليدوية السريعة."},{"number":5,"kind":"choice","prompt":"لماذا نترك فراغًا مدروسًا في تكوين ديواني؟","target":"","options":["لإخفاء الكلمة","لرفع السطر عن الصفحة","لإبراز الحروف ومنع التزاحم المفرط","لإلغاء اتصال العربية"],"answerIndex":2,"explanation":"الفراغ يوازن الكثافة ويحفظ مقروئية التكوين."},{"number":6,"kind":"order","prompt":"رتّب مراحل تمرين كلمة ديوانية بسيطة.","target":"","tokens":["وازن الفراغات","قرّب الوصلات","راجع الحروف","اكتب الكلمة"],"answer":["اكتب الكلمة","راجع الحروف","قرّب الوصلات","وازن الفراغات"],"explanation":"التسلسل الصحيح: اكتب الكلمة ← راجع الحروف ← قرّب الوصلات ← وازن الفراغات. "},{"number":7,"kind":"type","prompt":"اكتب اسم الخط المرتبط تاريخيًا بالدواوين العثمانية.","target":"","answer":"الديواني","explanation":"سُمّي الخط الديواني لارتباطه بالدواوين العثمانية."}]},{"index":9,"stage":{"title":"الفارسي والنستعليق","subtitle":"ميل السطر ومرونة الأقواس","intro":"النستعليق، ويُعرف عند كثير من المتعلمين باسم «الخط الفارسي»، تقليد كتابي اشتهر في بلاد فارس وجنوب آسيا. تبدو الكلمات في نماذج عديدة مائلة أو متدرجة على مستوى السطر، مع أقواس معلّقة وانسياب واضح. هذه الخصائص تحتاج إلى عين تميّز اتجاه الكلمة وتوازن الفراغ أكثر من مجرد ميل الحروف بصورة عشوائية. جرّب تخطيط كلمة «جمال» من اليمين إلى اليسار على محور إرشادي مائل قليلًا، ثم انظر إلى اتزان نهاياتها.","tips":["النستعليق لا يعني إمالة النسخ عشوائيًا.","راقب انسياب الوصلات والأقواس تحت المحور العام.","تطورت له تقاليد مهمة في إيران وشبه القارة الهندية.","استخدم ميلًا بسيطًا في التدريب دون ادعاء محاكاة كاملة للخط."],"practice":{"model":"جمال","focus":"محور مائل وأقواس متوازنة","instructions":"اكتب «جمال» على خط مائل خفيف، ثم اكتب «حياة» للمقارنة. راقب اتصال الحروف ومواضع الانحناء."}},"questions":[{"number":0,"kind":"choice","prompt":"ما الاسم المتداول لأسلوب يُعرف أيضًا بالخط الفارسي؟","target":"","options":["الكوفي الهندسي","الديواني الجلي","النستعليق","الرقعة"],"answerIndex":2,"explanation":"النستعليق معروف في تقاليد الخط الفارسي وجنوب آسيا."},{"number":1,"kind":"choice","prompt":"ما سمة بصرية شائعة في النستعليق؟","target":"","options":["غياب أي انحناء","ميل الكلمات والأقواس المعلّقة","الحروف المربعة فقط","حذف الوصلات كلها"],"answerIndex":1,"explanation":"يتميز النستعليق بإيقاع مائل وأقواس ممتدة."},{"number":2,"kind":"choice","prompt":"هل يكفي إمالة النسخ لتكوين نستعليق صحيح؟","target":"","options":["لا، للنستعليق بنية ونسب خاصة","نعم بشكل كامل","نعم إذا حذفنا النقاط","نعم إذا غيرنا اتجاه العربية"],"answerIndex":0,"explanation":"النستعليق نظام خطي مستقل وليس تعديلًا سطحيًا."},{"number":3,"kind":"choice","prompt":"أين تطورت تقاليد مهمة للنستعليق؟","target":"","options":["الأندلس وحدها","شمال أوروبا فقط","اليونان القديمة فقط","إيران وشبه القارة الهندية"],"answerIndex":3,"explanation":"اشتهر النستعليق في إيران ومناطق من جنوب آسيا."},{"number":4,"kind":"choice","prompt":"أي عنصر يحتاج إلى ضبط في تمرين الفارسي؟","target":"","options":["إلغاء السطر","حجم النقاط فقط","العلاقة بين محور الميل والأقواس","عدد الهواتف في الغرفة"],"answerIndex":2,"explanation":"التوازن بين ميل الكتابة وامتدادات الحروف أساسي."},{"number":5,"kind":"choice","prompt":"ما الخطأ الأكثر شيوعًا في محاكاته سريعًا؟","target":"","options":["مراجعة الانحناءات","ميل الحروف عشوائيًا بلا مراعاة النِّسب","استعمال ورق مسطر","قراءة الكلمة"],"answerIndex":1,"explanation":"لا يعوّض الميل العشوائي عن قواعد التكوين."},{"number":6,"kind":"order","prompt":"رتّب خطوات تمرين تعليمي لميل كلمة.","target":"","tokens":["تحقق من القراءة","وازن الأقواس","ارسم الهيكل","حدّد المحور"],"answer":["حدّد المحور","ارسم الهيكل","وازن الأقواس","تحقق من القراءة"],"explanation":"التسلسل الصحيح: حدّد المحور ← ارسم الهيكل ← وازن الأقواس ← تحقق من القراءة. "},{"number":7,"kind":"type","prompt":"اكتب اسم الخط المرتبط بالفارسي ذي الكلمات المائلة والأقواس المعلّقة.","target":"","answer":"النستعليق","explanation":"النستعليق أحد أهم تقاليد الخط الفارسي."}]},{"index":10,"stage":{"title":"الخط المغربي: تقاليد الغرب الإسلامي","subtitle":"استدارة الأشكال واختلاف بعض مواضع النقط","intro":"الخط المغربي ليس نسخة من خط النسخ المشرقي، بل مجموعة تقاليد كتابية تطورت في المغرب والأندلس ومناطق الغرب الإسلامي. تظهر في نماذج تاريخية منه أقواس مستديرة وأشكال مميزة للحروف؛ وفي بعض المخطوطات المغربية التقليدية توضع نقطة الفاء أسفل الحرف ونقطة واحدة للقاف فوقه، خلافًا للنظام المشرقي المعتاد. تختلف التفاصيل بحسب الحقبة والمدرسة، ولا تنطبق هذه القاعدة على كل طباعة مغاربية حديثة. تعلّم ملاحظة السياق قبل الحكم على حرف غريب في مخطوطة.","tips":["تعرف على المغاربي بوصفه أساليب متعددة لا نموذجًا واحدًا.","في بعض المخطوطات التقليدية قد تظهر نقطة الفاء أسفلها.","القاف في تقاليد مغربية تُنقط أحيانًا بنقطة واحدة فوقها.","لا تعمم أنظمة تنقيط المخطوطات على كل كتب المغرب الحديثة."],"practice":{"model":"مغرب   فقه","focus":"ملاحظة أقواس الحروف والتنقيط الإقليمي","instructions":"اكتب «مغرب» و«فقه» كتابة عربية مقروءة. ضع أسفل الرسم ملاحظة عن اختلاف تنقيط الفاء والقاف في بعض المخطوطات المغربية التاريخية."}},"questions":[{"number":0,"kind":"choice","prompt":"أين تطورت تقاليد مهمة للخط المغربي؟","target":"","options":["البلقان وحده","المغرب والأندلس والغرب الإسلامي","شرق آسيا فقط","إيطاليا الحديثة فقط"],"answerIndex":1,"explanation":"يُعرف الخط المغربي في تقاليد المخطوطات الغربية الإسلامية."},{"number":1,"kind":"choice","prompt":"في بعض المخطوطات المغربية التقليدية، أين تقع نقطة الفاء؟","target":"","options":["أسفل الحرف","فوق الحرف دائمًا","داخل الميم","في هامش الصفحة"],"answerIndex":0,"explanation":"توجد تقاليد تاريخية تجعل نقطة الفاء تحت الحرف."},{"number":2,"kind":"choice","prompt":"كيف تُنقط القاف في بعض التقاليد المغربية القديمة؟","target":"","options":["بثلاث نقاط تحتها","دون أي حرف","بنقطتين أسفلها","بنقطة واحدة فوقها"],"answerIndex":3,"explanation":"القاف بنقطة واحدة فوقها من السمات المعروفة في نماذج مغربية تاريخية."},{"number":3,"kind":"choice","prompt":"هل تتبع جميع المطبوعات المغاربية الحديثة تنقيط المخطوطات التقليدي؟","target":"","options":["لا تحتوي أي نقاط","تستخدم نقاطًا على الهوامش فقط","لا، تختلف التقاليد والطبعات","نعم دائمًا"],"answerIndex":2,"explanation":"كثير من المطبوعات الحديثة يستخدم النقط المشرقي المتداول."},{"number":4,"kind":"choice","prompt":"ما سمة بصرية شائعة في الخطوط المغربية التاريخية؟","target":"","options":["شبكة مربعة في كل الأمثلة","أقواس مستديرة وبنية إقليمية متنوعة","أحرف لاتينية فقط","خطوط بلا حروف متصلة"],"answerIndex":1,"explanation":"تظهر أشكال مستديرة وتنوّع في الصياغة الإقليمية."},{"number":5,"kind":"choice","prompt":"كيف نقرأ حرفًا غير مألوف في مخطوطة مغربية؟","target":"","options":["نراجع سياق الكلمة ونظام النقط","نرفض قراءته مباشرة","نستبدله عشوائيًا","نهمل السطر كله"],"answerIndex":0,"explanation":"يساعد السياق ونظام التنقيط الإقليمي على التمييز."},{"number":6,"kind":"order","prompt":"رتّب خطوات فحص حرف في مخطوطة تاريخية.","target":"","tokens":["قارن بنظائره","اقرأ السياق","افحص النقط","لاحظ شكل الحرف"],"answer":["لاحظ شكل الحرف","افحص النقط","اقرأ السياق","قارن بنظائره"],"explanation":"التسلسل الصحيح: لاحظ شكل الحرف ← افحص النقط ← اقرأ السياق ← قارن بنظائره. "},{"number":7,"kind":"type","prompt":"اكتب اسم الخط المرتبط بتقاليد الأندلس والغرب الإسلامي.","target":"","answer":"المغربي","explanation":"تطورت تقاليد الخط المغربي في المغرب والأندلس والغرب الإسلامي."}]},{"index":11,"stage":{"title":"المشروع الختامي: لوحة بخط عربي","subtitle":"اختيار الأسلوب وكتابة جملة كاملة ومراجعتها","intro":"وصلت إلى المحطة الأخيرة. الآن لا تكفي معرفة أسماء الخطوط؛ عليك اتخاذ قرارات واعية عند إعداد لوحة قصيرة. اختر عبارة حقيقية مثل «اليمن أرض الحضارة والتاريخ»، وحدّد هدفها: لوحة عنوانية، نص للقراءة، أم بطاقة شخصية. للوضوح الطويل يُناسب النسخ أكثر، وللكتابة اليومية الرقعة، وللعرض الزخرفي قد تختار أسلوبًا من الثلث أو الكوفي وفق قدرتك. ابدأ برسم تخطيط على الورق، ثم جرّب الحروف، واضبط الفراغات، وراجع صحة النص قبل الزخارف. يمكنك تكرار المشروع وتحسينه بعد إنهاء الاختبار.","tips":["حدد جمهور اللوحة ووظيفتها قبل اختيار الخط.","اكتب الجملة كاملة بلا أخطاء إملائية قبل تجميلها.","قسّم مساحة اللوحة إلى عنوان وفراغات متوازنة.","راجع النقاط والوصلات ومقروئية الكلمات، ثم جرّب نسخة ثانية محسّنة."],"practice":{"model":"اليمن أرض الحضارة والتاريخ","focus":"لوحة متكاملة بجملة ذات معنى","instructions":"اكتب «اليمن أرض الحضارة والتاريخ» في اللوحة التدريبية. أنشئ نسختين: الأولى واضحة للقراءة، والثانية بتكوين زخرفي مدروس، ثم قارن بينهما."}},"questions":[{"number":0,"kind":"choice","prompt":"ما أول قرار قبل رسم لوحة خطية؟","target":"","options":["تحديد الغرض والجمهور والنص","اختيار أكثر زخرفة ممكنة دائمًا","حذف المسافات","اختيار لون عشوائي"],"answerIndex":0,"explanation":"يحدد الغرض طريقة اختيار الخط والتكوين."},{"number":1,"kind":"choice","prompt":"أي خط مناسب عادة لنص طويل يحتاج إلى وضوح؟","target":"","options":["الديواني الجلي المزدحم","الكوفي المربع الزخرفي فقط","الثلث المتشابك فقط","النسخ"],"answerIndex":3,"explanation":"يمتاز النسخ بوضوح الحروف وملاءمته للنصوص المقروءة."},{"number":2,"kind":"choice","prompt":"ما المناسب عادة لملاحظات سريعة يومية؟","target":"","options":["الديواني الجلي","الكوفي الهندسي","الرقعة","الثلث الزخرفي"],"answerIndex":2,"explanation":"الرقعة خط عملي للكتابة اليومية."},{"number":3,"kind":"choice","prompt":"ماذا تفعل قبل إضافة زخارف إلى عبارة؟","target":"","options":["تغير ترتيب الكلمات","تتحقق من سلامة النص ووضوحه","تحذف الحركات والنقط جميعها","تدمج كلمتين بالضرورة"],"answerIndex":1,"explanation":"تعتمد جودة اللوحة أولًا على صحة العبارة وإمكان قراءتها."},{"number":4,"kind":"choice","prompt":"لماذا تُنشئ تخطيطًا أوليًا؟","target":"","options":["لاختبار توزيع الكلمات والفراغات","لإخفاء النص","لإلغاء مراجعة النقط","لزيادة وقت الكتابة فقط"],"answerIndex":0,"explanation":"التخطيط المسبق يسهّل مراجعة النِّسب والتكوين."},{"number":5,"kind":"choice","prompt":"ما أفضل طريقة للتعلم بعد إنجاز اللوحة الأولى؟","target":"","options":["التوقف عن الممارسة نهائيًا","تغيير موضوع الخط دون مراجعة","حذف الأخطاء دون فهمها","مقارنتها بنسخة ثانية مع ملاحظات محددة"],"answerIndex":3,"explanation":"المقارنة الواعية والتكرار يدعمان تطور المهارة."},{"number":6,"kind":"order","prompt":"رتّب خطوات إنجاز اللوحة النهائية.","target":"","tokens":["راجع اللوحة","اكتب مسودة","حدّد الخط","اختر العبارة"],"answer":["اختر العبارة","حدّد الخط","اكتب مسودة","راجع اللوحة"],"explanation":"التسلسل الصحيح: اختر العبارة ← حدّد الخط ← اكتب مسودة ← راجع اللوحة. "},{"number":7,"kind":"type","prompt":"أكمل الجملة الختامية: «اليمن أرض الحضارة و...».","target":"","answer":"التاريخ","explanation":"الجملة الختامية الكاملة هي «اليمن أرض الحضارة والتاريخ»."}]}]}$school967$::jsonb);

insert into public.school_editor_courses(slug,draft,published,version,published_version,updated_by)
select payload->>'slug',payload->'course',payload->'course',1,1,null
from pg_temp.school967_calligraphy_seed on conflict (slug) do nothing;

insert into public.school_editor_stages(course_slug,stage_index,draft,published,version,published_version,updated_by)
select c.payload->>'slug',(s.item->>'index')::integer,s.item->'stage',s.item->'stage',1,1,null
from pg_temp.school967_calligraphy_seed c cross join lateral jsonb_array_elements(c.payload->'stages') as s(item)
on conflict (course_slug,stage_index) do nothing;

insert into public.school_editor_questions(id,course_slug,stage_index,draft,published,version,published_version,updated_by)
select md5('arabic-calligraphy:v1:'||(s.item->>'index')||':'||(q.item->>'number'))::uuid,
c.payload->>'slug',(s.item->>'index')::integer,
q.item-'number',q.item-'number',1,1,null
from pg_temp.school967_calligraphy_seed c
cross join lateral jsonb_array_elements(c.payload->'stages') as s(item)
cross join lateral jsonb_array_elements(s.item->'questions') as q(item)
on conflict (id) do nothing;
